import * as React from "react";
import {
  Checkbox as RC,
  Switch as RS,
  Slider as SL,
  Select as SE,
  RadioGroup as RG,
  Toggle as TO,
  ToggleGroup as TG,
} from "radix-ui";
import { Check, Minus, ChevronDown } from "lucide-react";
import { DayPicker } from "react-day-picker";
import { cx } from "./utils";
export const Input = React.forwardRef<
  HTMLInputElement,
  React.InputHTMLAttributes<HTMLInputElement>
>(function Input({ className, ...p }, ref) {
  return <input ref={ref} className={cx("a-input", className)} {...p} />;
});
export const Textarea = React.forwardRef<
  HTMLTextAreaElement,
  React.TextareaHTMLAttributes<HTMLTextAreaElement>
>(function Textarea({ className, ...p }, ref) {
  return (
    <textarea
      ref={ref}
      rows={4}
      className={cx("a-input resize-y", className)}
      {...p}
    />
  );
});
export function Label(p: React.LabelHTMLAttributes<HTMLLabelElement>) {
  return <label {...p} className={cx("text-sm font-medium", p.className)} />;
}
export function Field({
  label,
  hint,
  error,
  children,
}: {
  label: string;
  hint?: string;
  error?: string;
  children: React.ReactElement;
}) {
  const id = React.useId();
  const description =
    [hint ? id + "-hint" : "", error ? id + "-error" : ""]
      .filter(Boolean)
      .join(" ") || undefined;
  return (
    <div className="grid gap-2">
      <Label htmlFor={id}>{label}</Label>
      {React.cloneElement(
        children as React.ReactElement<React.HTMLAttributes<HTMLElement>>,
        {
          id,
          "aria-describedby": description,
          "aria-invalid": error ? true : undefined,
        },
      )}
      {hint && (
        <p id={id + "-hint"} className="text-xs text-muted">
          {hint}
        </p>
      )}
      {error && (
        <p role="alert" id={id + "-error"} className="text-xs text-danger">
          {error}
        </p>
      )}
    </div>
  );
}
export function InputGroup({
  prefix,
  suffix,
  children,
}: {
  prefix?: React.ReactNode;
  suffix?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="flex items-center gap-2 rounded-lg border border-line bg-card px-3 [&_input]:border-0 [&_input]:bg-transparent">
      <span className="text-sm text-muted">{prefix}</span>
      {children}
      <span className="text-sm text-muted">{suffix}</span>
    </div>
  );
}
export function Checkbox({
  label,
  description,
  error,
  className,
  "aria-describedby": describedBy,
  "aria-invalid": invalid,
  ...props
}: React.ComponentProps<typeof RC.Root> & {
  label: React.ReactNode;
  /** Help text linked to the control through aria-describedby. */
  description?: React.ReactNode;
  /** Validation message; marks the control invalid and links the text. */
  error?: React.ReactNode;
}) {
  const generatedId = React.useId();
  const id = props.id ?? generatedId;
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const indeterminate = props.checked === "indeterminate";
  return (
    <div className={cx("flex items-start gap-3 py-3", className)}>
      <RC.Root
        id={id}
        {...props}
        aria-invalid={error ? true : invalid}
        aria-describedby={
          [describedBy, descriptionId, errorId].filter(Boolean).join(" ") ||
          undefined
        }
        className="mt-0.5 flex size-5 shrink-0 items-center justify-center rounded border border-control bg-card transition-colors hover:border-ink data-[state=checked]:border-ink data-[state=checked]:bg-ink data-[state=checked]:text-paper data-[state=indeterminate]:border-ink data-[state=indeterminate]:bg-ink data-[state=indeterminate]:text-paper aria-invalid:border-danger disabled:cursor-default disabled:opacity-40 disabled:hover:border-control"
      >
        <RC.Indicator>
          {indeterminate ? (
            <Minus className="size-3.5" strokeWidth={2.5} />
          ) : (
            <Check className="size-3.5" strokeWidth={2.5} />
          )}
        </RC.Indicator>
      </RC.Root>
      <div className="grid min-w-0 gap-1">
        <label htmlFor={id} className="text-sm leading-6">
          {label}
        </label>
        {description && (
          <p id={descriptionId} className="text-xs leading-relaxed text-muted">
            {description}
          </p>
        )}
        {error && (
          <p id={errorId} role="alert" className="text-xs leading-relaxed text-danger">
            {error}
          </p>
        )}
      </div>
    </div>
  );
}
export function Switch({
  label,
  className,
  ...props
}: React.ComponentProps<typeof RS.Root> & { label: string }) {
  const generatedId = React.useId();
  const id = props.id ?? generatedId;
  return (
    <div className="flex min-h-11 items-center gap-3">
      <RS.Root
        id={id}
        {...props}
        className={cx(
          "relative w-10 shrink-0 rounded-full border border-line bg-surface p-0.5 data-[state=checked]:bg-terracotta disabled:opacity-40",
          className,
        )}
      >
        <RS.Thumb className="relative start-0 block size-4 rounded-full bg-card transition-[inset-inline-start] data-[state=checked]:start-[calc(100%-16px)] motion-reduce:transition-none" />
      </RS.Root>
      <label htmlFor={id} className="text-sm">
        {label}
      </label>
    </div>
  );
}
export function RadioGroup({
  label,
  options,
  focusRef,
  ...props
}: React.ComponentProps<typeof RG.Root> & {
  label: string;
  focusRef?: React.Ref<HTMLButtonElement>;
  options: { value: string; label: string; disabled?: boolean }[];
}) {
  const uid = React.useId();
  const firstEnabled = props.disabled ? -1 : options.findIndex(option => !option.disabled);
  return (
    <RG.Root aria-label={label} {...props} className="grid gap-3">
      {options.map((o, i) => (
        <div className="flex items-center gap-3" key={o.value}>
          <RG.Item
            ref={i === firstEnabled ? focusRef : undefined}
            id={uid + i}
            value={o.value}
            disabled={o.disabled}
            className="flex size-5 items-center justify-center rounded-full border border-line disabled:opacity-40"
          >
            <RG.Indicator className="size-2.5 rounded-full bg-terracotta" />
          </RG.Item>
          <Label htmlFor={uid + i}>{o.label}</Label>
        </div>
      ))}
    </RG.Root>
  );
}
export function NativeSelect({
  options,
  ...props
}: React.ComponentPropsWithRef<"select"> & {
  options: { value: string; label: string; disabled?: boolean }[];
}) {
  return (
    <select {...props} className={cx("a-input", props.className)}>
      {options.map((o) => (
        <option key={o.value} {...o}>
          {o.label}
        </option>
      ))}
    </select>
  );
}
export function Select({
  label,
  options,
  triggerRef,
  triggerOnBlur,
  placeholder = "Choose an option",
  id,
  "aria-invalid": invalid,
  "aria-describedby": describedBy,
  ...props
}: React.ComponentProps<typeof SE.Root> & {
  triggerRef?: React.Ref<HTMLButtonElement>;
  triggerOnBlur?: React.FocusEventHandler<HTMLButtonElement>;
  id?: string;
  "aria-invalid"?: React.AriaAttributes["aria-invalid"];
  "aria-describedby"?: string;
  label: string;
  placeholder?: string;
  options: {
    value: string;
    label: string;
    disabled?: boolean;
    description?: string;
    swatch?: string;
  }[];
}) {
  return (
    <SE.Root {...props}>
      <SE.Trigger
        ref={triggerRef}
        onBlur={triggerOnBlur}
        id={id}
        aria-invalid={invalid}
        aria-describedby={describedBy}
        aria-label={label}
        className="a-input flex items-center justify-between gap-3 text-start data-[state=open]:border-terracotta [&>span:first-child]:min-w-0 [&>span:first-child]:truncate"
      >
        <SE.Value placeholder={placeholder} />
        <SE.Icon>
          <ChevronDown className="size-4 shrink-0 text-muted" />
        </SE.Icon>
      </SE.Trigger>
      <SE.Portal>
        <SE.Content
          className="a-popup w-[var(--radix-select-trigger-width)] min-w-[min(12rem,calc(100vw-24px))] max-w-[calc(100vw-24px)] overflow-hidden p-1.5"
          position="popper"
          sideOffset={6}
          collisionPadding={12}
        >
          <SE.Viewport className="a-scrollbar max-h-[min(320px,var(--radix-select-content-available-height))] space-y-1 p-0.5">
            {options.map((o) => (
              <SE.Item
                key={o.value}
                value={o.value}
                disabled={o.disabled}
                textValue={o.label}
                className="relative flex min-h-11 cursor-default items-center gap-3 rounded-md px-3 py-2.5 text-sm outline-none data-[state=checked]:bg-surface data-[highlighted]:ring-1 data-[highlighted]:ring-inset data-[highlighted]:ring-terracotta data-[disabled]:pointer-events-none data-[disabled]:opacity-40"
              >
                {o.swatch && (
                  <span
                    aria-hidden="true"
                    className="size-5 shrink-0 rounded-full border border-line"
                    style={{ backgroundColor: o.swatch }}
                  />
                )}
                <span className="min-w-0 flex-1 break-words">
                  <SE.ItemText>{o.label}</SE.ItemText>
                  {o.description && (
                    <span className="mt-1 block text-xs leading-relaxed text-muted">
                      {o.description}
                    </span>
                  )}
                </span>
                <span className="flex size-4 shrink-0 items-center justify-center">
                  <SE.ItemIndicator>
                    <Check className="size-4" />
                  </SE.ItemIndicator>
                </span>
              </SE.Item>
            ))}
          </SE.Viewport>
        </SE.Content>
      </SE.Portal>
    </SE.Root>
  );
}
export function Slider({
  label,
  ...props
}: React.ComponentProps<typeof SL.Root> & { label: string }) {
  const values = props.value || props.defaultValue || [50];
  return (
    <SL.Root
      {...props}
      defaultValue={props.defaultValue || (!props.value ? [50] : undefined)}
      className="relative flex h-8 w-full touch-none items-center"
    >
      <SL.Track className="relative h-1.5 grow rounded-full bg-surface">
        <SL.Range className="absolute h-full rounded-full bg-terracotta" />
      </SL.Track>
      {values.map((_, i) => (
        <SL.Thumb
          key={i}
          aria-label={values.length > 1 ? label + " " + (i + 1) : label}
          className="block size-5 rounded-full border border-line bg-card shadow-sm"
        />
      ))}
    </SL.Root>
  );
}
export function Toggle({
  children,
  ...props
}: React.ComponentProps<typeof TO.Root>) {
  return (
    <TO.Root
      {...props}
      className="a-button min-h-10 border border-line px-3 text-sm data-[state=on]:bg-ink data-[state=on]:text-paper"
    >
      {children}
    </TO.Root>
  );
}
export function ToggleGroup({
  label,
  options,
  value,
  onValueChange,
}: {
  label: string;
  options: string[];
  value?: string;
  onValueChange?: (v: string) => void;
}) {
  return (
    <TG.Root
      type="single"
      aria-label={label}
      value={value}
      onValueChange={onValueChange}
      className="inline-flex gap-1 rounded-lg bg-surface p-1"
    >
      {options.map((o) => (
        <TG.Item
          key={o}
          value={o}
          className="rounded-md px-3 py-2 text-sm data-[state=on]:bg-card"
        >
          {o}
        </TG.Item>
      ))}
    </TG.Root>
  );
}
export function Calendar({
  className,
  showOutsideDays = true,
  navLayout = "after",
  ...props
}: React.ComponentProps<typeof DayPicker>) {
  return (
    <DayPicker
      {...props}
      className={cx("a-calendar", className)}
      showOutsideDays={showOutsideDays}
      navLayout={navLayout}
    />
  );
}
export function DatePicker(
  props: Omit<React.InputHTMLAttributes<HTMLInputElement>, "type">,
) {
  return <Input {...props} type="date" />;
}
export function Combobox({
  label,
  options,
  ...props
}: React.InputHTMLAttributes<HTMLInputElement> & {
  label: string;
  options: string[];
}) {
  const id = React.useId();
  return (
    <>
      <Input {...props} aria-label={label} list={id} />
      <datalist id={id}>
        {options.map((o) => (
          <option key={o} value={o} />
        ))}
      </datalist>
    </>
  );
}
export function InputOTP({
  length = 6,
  label = "Verification code",
  value,
  onChange,
  disabled,
}: {
  length?: number;
  label?: string;
  value: string;
  onChange: (v: string) => void;
  disabled?: boolean;
}) {
  return (
    <Input
      aria-label={label}
      inputMode="numeric"
      autoComplete="one-time-code"
      value={value}
      disabled={disabled}
      maxLength={length}
      pattern={"[0-9]{" + length + "}"}
      onChange={(e) =>
        onChange(e.target.value.replace(/\D/g, "").slice(0, length))
      }
      className="max-w-64 text-center font-mono text-xl tracking-[0.5em]"
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export const cx = (...values: ClassValue[]) => twMerge(clsx(values));

@import "tailwindcss";
@import "@fontsource-variable/dm-sans";
@import "@fontsource-variable/lora";
@import "./motion.css";
@import "./effects.css";
@source "./**/*.{ts,tsx}";
@theme {
  --default-transition-duration: 220ms;
  --default-transition-timing-function: cubic-bezier(.2, .7, .2, 1);
  --color-paper: #f4f1e9;
  --color-ink: #20201d;
  --color-muted: #656158;
  --color-line: #d2ccc0;
  --color-control: #898d80;
  --color-surface: #e8e3d8;
  --color-card: #faf8f2;
  --color-terracotta: #ac4333;
  --color-gold: #edbd52;
  --color-danger: #a32925;
  --color-on-danger: #ffffff;
  --color-success: #326145;
  --color-chart-3: #b4bdb0;
  --color-chart-4: #cfc5ad;
  --color-chart-5: #8b9fa2;
  --radius-lg: 9px;
  --radius-xl: 16px;
  --radius-2xl: 22px;
  --font-sans: "DM Sans Variable", Arial, sans-serif;
  --font-editorial: "Lora Variable", Georgia, serif;
}
@layer base {
  * {
    border-color: var(--color-line);
  }
  body {
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
    margin: 0;
    -webkit-font-smoothing: antialiased;
  }
  button:not(:disabled),
  summary {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid var(--color-terracotta);
    outline-offset: 4px;
  }
}
.a-scroll-track { width: 14px; padding: 16px 4px; background: transparent; touch-action: none; user-select: none; }
.a-scroll-thumb { min-height: 32px; border-radius: 999px; background: color-mix(in srgb, var(--color-muted) 32%, transparent); transition: background-color var(--motion-normal) var(--motion-ease); }
.a-scroll-track:hover .a-scroll-thumb, .a-scroll-thumb:active { background: color-mix(in srgb, var(--color-muted) 72%, transparent); }
/* Native scroll surfaces inside components share the ScrollArea thumb: a 6px pill on a transparent track. */
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar { width: 12px; height: 12px; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-track { background: transparent; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb { border: 3px solid transparent; border-radius: 999px; background: color-mix(in srgb, var(--color-muted) 32%, transparent); background-clip: padding-box; min-height: 32px; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb:hover, :is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb:active { background-color: color-mix(in srgb, var(--color-muted) 72%, transparent); }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-corner { background: transparent; }
@supports not selector(::-webkit-scrollbar) {
  :is(.a-scrollbar, .a-popup, .a-modal-content) { scrollbar-width: thin; scrollbar-color: color-mix(in srgb, var(--color-muted) 32%, transparent) transparent; }
}
@layer components {
  .a-card{
    padding:var(--space-card,24px);
    border:var(--card-border-width,1px) solid var(--color-card-border,var(--color-line));
    border-top-width:var(--card-top-width,1px);
    box-shadow:var(--shadow-card,none);
  }
  .a-button {
    @apply inline-flex shrink-0 items-center justify-center gap-2 rounded-lg font-medium transition-[background-color,color,border-color,box-shadow,transform] disabled:pointer-events-none disabled:opacity-45 focus-visible:outline-2 focus-visible:outline-offset-4 active:translate-y-px;
    letter-spacing: -0.015em;
    max-width: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
  }
  .a-input {
    @apply min-h-10 w-full rounded-lg border border-line bg-paper/50 px-3 py-2 text-sm text-ink shadow-xs placeholder:text-muted/75 disabled:opacity-50 read-only:bg-surface/70 read-only:shadow-none read-only:focus-visible:bg-surface/70 aria-invalid:border-danger focus-visible:bg-card transition-colors;
  }
  .a-overlay {
    @apply fixed inset-0 z-50 bg-black/40 backdrop-blur-xs;
  }
  .a-popup {
    @apply z-50 rounded-xl border border-line bg-card p-2 text-ink shadow-xl;
    max-width: calc(100vw - 24px);
    max-height: min(
      80dvh,
      var(--radix-popover-content-available-height, 80dvh)
    );
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--color-menu, var(--color-card));
  }
}
.a-modal-content {
  overflow-wrap: anywhere;
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
.a-input {
  min-width: 0;
}
progress {
  appearance: none;
  height: 8px;
  background: var(--color-surface);
}
progress::-webkit-progress-bar {
  background: var(--color-surface);
  border-radius: 100px;
}
progress::-webkit-progress-value {
  background: var(--color-terracotta);
  border-radius: 100px;
}
progress::-moz-progress-bar {
  background: var(--color-terracotta);
  border-radius: 100px;
}
.a-calendar {
  --cal-radius: 10px;
  --cal-target: 44px;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  color: var(--color-ink);
  width: 100%;
  max-width: 100%;
  --rdp-accent-color: var(--color-terracotta);
}
.a-calendar .rdp-months {
  display: flex;
  flex-wrap: wrap;
  gap: 32px;
  align-items: start;
}
.a-calendar .rdp-month {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  flex: 1 1 260px;
  min-width: 0;
  gap: 10px 8px;
  /* Zoomed text may need more than the parent width; the month then scrolls as a bounded region instead of overlapping digits. */
  overflow-x: auto;
}
.a-calendar .rdp-month_caption {
  flex: 1 1 auto;
  min-width: 0;
  padding-inline-start: 6px;
  font-family: var(--font-editorial);
  font-size: 1.125rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  overflow-wrap: break-word;
}
.a-calendar .rdp-caption_label {
  line-height: 1.4;
}
.a-calendar .rdp-nav {
  display: flex;
  gap: 6px;
  margin: 0;
  margin-inline-start: auto;
}
.a-calendar .rdp-month_grid {
  flex: 1 0 100%;
  border-collapse: separate;
  border-spacing: 0 2px;
  width: 100%;
  table-layout: auto;
}
.a-calendar th {
  width: 14.28%;
  min-width: 1.75em;
  height: 36px;
  color: var(--color-muted);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: center;
  white-space: nowrap;
}
.a-calendar td {
  width: 14.28%;
  min-width: 1.75em;
  height: var(--cal-target);
  padding: 0;
  text-align: center;
}
.a-calendar .rdp-week_number {
  width: auto;
  min-width: 1.5em;
  padding-inline-end: 6px;
  color: var(--color-muted);
  font-size: 0.6875rem;
  letter-spacing: 0.04em;
}
.a-calendar button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 24px;
  min-height: var(--cal-target);
  border: 1px solid transparent;
  border-radius: var(--cal-radius);
  color: inherit;
  background: transparent;
  font: inherit;
  line-height: 1;
  touch-action: manipulation;
  transition:
    background-color var(--motion-fast, 140ms) var(--motion-ease, ease-out),
    color var(--motion-fast, 140ms) var(--motion-ease, ease-out),
    border-color var(--motion-fast, 140ms) var(--motion-ease, ease-out);
}
.a-calendar button:hover:not(:disabled):not([aria-disabled="true"]) {
  background: var(--color-surface);
}
.a-calendar button:focus-visible {
  outline-offset: -3px;
  z-index: 1;
}
.a-calendar [data-today="true"] button {
  font-weight: 600;
}
.a-calendar [data-today="true"] button::after {
  content: "";
  position: absolute;
  bottom: 6px;
  left: 50%;
  width: 4px;
  height: 4px;
  border-radius: 999px;
  background: var(--color-terracotta);
  translate: -50% 0;
}
.a-calendar [data-outside="true"] button {
  color: color-mix(in srgb, var(--color-muted) 65%, transparent);
}
.a-calendar [aria-selected="true"] button {
  background: var(--color-ink);
  color: var(--color-paper);
}
.a-calendar [aria-selected="true"] button::after {
  background: var(--color-paper);
}
.a-calendar [aria-selected="true"] button:hover:not(:disabled) {
  background: var(--color-ink);
}
.a-calendar .rdp-range_middle {
  background: var(--color-surface);
}
.a-calendar .rdp-range_middle button {
  background: transparent;
  color: var(--color-ink);
  border-radius: 0;
}
.a-calendar .rdp-range_middle button::after {
  background: var(--color-terracotta);
}
.a-calendar .rdp-range_middle button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--color-ink) 8%, var(--color-surface));
}
.a-calendar .rdp-range_start:not(.rdp-range_end) {
  background: linear-gradient(to right, transparent 50%, var(--color-surface) 50%);
}
.a-calendar .rdp-range_end:not(.rdp-range_start) {
  background: linear-gradient(to left, transparent 50%, var(--color-surface) 50%);
}
.a-calendar[dir="rtl"] .rdp-range_start:not(.rdp-range_end) {
  background: linear-gradient(to left, transparent 50%, var(--color-surface) 50%);
}
.a-calendar[dir="rtl"] .rdp-range_end:not(.rdp-range_start) {
  background: linear-gradient(to right, transparent 50%, var(--color-surface) 50%);
